Here is the commit message:
spi: tegra: checking for ERR_PTR instead of NULL

dma_request_slave_channel() returns NULL on error and not ERR_PTRs.
I've fixed this by using dma_request_slave_channel_reason() which does
return ERR_PTRs.

Fixes: a915d150f68d ('spi: tegra: convert to standard DMA DT bindings')
Signed-off-by: Dan Carpenter <dan.carpenter@oracle.com>
Signed-off-by: Stephen Warren <swarren@nvidia.com>

Here is the root cause:
The bug was caused by using `dma_request_slave_channel()`, which returns `NULL` on error, instead of `dma_request_slave_channel_reason()`, which returns an `ERR_PTR`. This led to incorrect error handling, as the code was not properly checking for error conditions, potentially allowing the program to proceed with an invalid DMA channel.

Here is the patch:

 static int tegra_slink_init_dma_param(struct tegra_slink_data *tspi,
 			bool dma_to_memory)
 {
 	struct dma_chan *dma_chan;
 	u32 *dma_buf;
 	dma_addr_t dma_phys;
 	int ret;
 	struct dma_slave_config dma_sconfig;

-	dma_chan = dma_request_slave_channel(tspi->dev,
-					     dma_to_memory ? "rx" : "tx");
+	dma_chan = dma_request_slave_channel_reason(tspi->dev,
+						dma_to_memory ? "rx" : "tx");
 	if (IS_ERR(dma_chan)) {
 		ret = PTR_ERR(dma_chan);
 		if (ret != -EPROBE_DEFER)
 			dev_err(tspi->dev,
 				"Dma channel is not available: %d\n", ret);
 		return ret;
 	}

 	dma_buf = dma_alloc_coherent(tspi->dev, tspi->dma_buf_size,
 				&dma_phys, GFP_KERNEL);
 	if (!dma_buf) {
 		dev_err(tspi->dev, " Not able to allocate the dma buffer\n");
 		dma_release_channel(dma_chan);
 		return -ENOMEM;
 	}

 	if (dma_to_memory) {
 		dma_sconfig.src_addr = tspi->phys + SLINK_RX_FIFO;
 		dma_sconfig.src_addr_width = DMA_SLAVE_BUSWIDTH_4_BYTES;
 		dma_sconfig.src_maxburst = 0;
 	} else {
 		dma_sconfig.dst_addr = tspi->phys + SLINK_TX_FIFO;
 		dma_sconfig.dst_addr_width = DMA_SLAVE_BUSWIDTH_4_BYTES;
 		dma_sconfig.dst_maxburst = 0;
 	}

 	ret = dmaengine_slave_config(dma_chan, &dma_sconfig);
 	if (ret)
 		goto scrub;
 	if (dma_to_memory) {
 		tspi->rx_dma_chan = dma_chan;
 		tspi->rx_dma_buf = dma_buf;
 		tspi->rx_dma_phys = dma_phys;
 	} else {
 		tspi->tx_dma_chan = dma_chan;
 		tspi->tx_dma_buf = dma_buf;
 		tspi->tx_dma_phys = dma_phys;
 	}
 	return 0;

 scrub:
 	dma_free_coherent(tspi->dev, tspi->dma_buf_size, dma_buf, dma_phys);
 	dma_release_channel(dma_chan);
 	return ret;
 }



